const rawContent = $('Switch').first().json.body.data.content;
const stringContent = typeof rawContent === 'string' ? rawContent : JSON.stringify(rawContent, null, 2);

return {
    json: { 
        fileName: "rubric.json",
        parentFolderId: $input.first().json.parents[0]
    },
    binary: {
        data: {
            data: Buffer.from(stringContent, 'utf-8').toString('base64'),
            mimeType: 'application/json',
            fileName: "rubric.json",
            fileExtension: 'json'
        }
    }
};

const clientRubrics =  $('Switch update/delete').first().json.body.data.selected_rubrics|| [];
const driveFolders = $input.all().map(item => ({
    folder_id: item.json.id,
    rubric_id: item.json.properties ? item.json.properties.file_rubric_id : null,
    de_id: item.json.properties ? item.json.properties.file_de_id : null
}));

// 1. Tìm các đề CẦN THÊM MỚI (Có trên Client nhưng chưa có trên Drive)
const toAdd = clientRubrics.filter(client => 
    !driveFolders.some(drive => drive.rubric_id === client.file_rubric_id)
);

// 2. Tìm các đề CẦN XÓA (Có trên Drive nhưng Client đã bỏ check)
const toDelete = driveFolders.filter(drive => 
    !clientRubrics.some(client => client.file_rubric_id === drive.rubric_id)
);

return {
    json: {
        has_add: toAdd.length > 0,
        has_delete: toDelete.length > 0,
        to_add: toAdd,
        to_delete: toDelete
    }
};

