const currentExam = $('Loop Over Items3').first().json;
const folderId = currentExam.id || currentExam.Folder_ID;

const allRows = $('Get row(s) in sheet').all();
const matchedRow = allRows.find(row => row.json.Folder_ID === folderId);

const currentStatus = matchedRow ? matchedRow.json.Status : "NOT_FOUND";
const startTime = matchedRow ? matchedRow.json.Start_Time : null;
const endTime = matchedRow ? matchedRow.json.End_Time : null;

const rubricsData = $input.all().map(item => {
    return item.json; 
});


const resultFolderId = $('Loop Over Items3').first().json.properties.result_id|| null;

return {
    json: {
        id: folderId,
        name: currentExam.Exam_Name || currentExam.name, 
        start: startTime,
        end: endTime,
        status: currentStatus,
        result_id: resultFolderId,
        rubrics: rubricsData
    }
};

